int main(int argc, char* argv[]) {
    mt19937 rng(argc > 1 ? atoi(argv[1]) : 1);
    auto los = [&](int a, int b) { return uniform_int_distribution<int>(a, b)(rng); };
    int n = los(1, 8);                 // MAŁE dane — łatwiej znaleźć i zrozumieć błąd
