// brute.cpp — maksymalna suma spójnego fragmentu w O(n^3): oczywiście poprawne
int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    long long best = LLONG_MIN;
    for (int l = 0; l < n; l++)
        for (int r = l; r < n; r++) {
            long long s = 0;
            for (int k = l; k <= r; k++) s += a[k];
            best = max(best, s);
        }
    cout << best << '\n';
}

#include <bits/stdc++.h>
using namespace std;

// Losowe drzewo: ojciec wierzchołka i to losowy z 1..i-1, potem losowa permutacja etykiet
int main(int argc, char* argv[]) {
    mt19937 rng(argc > 1 ? atoi(argv[1]) : 1);
    int n = uniform_int_distribution<int>(1, 10)(rng);
    vector<int> perm(n);
    iota(perm.begin(), perm.end(), 1);
    shuffle(perm.begin(), perm.end(), rng);
    cout << n << '\n';
    for (int i = 2; i <= n; i++) {
        int p = uniform_int_distribution<int>(1, i - 1)(rng);
        cout << perm[p - 1] << ' ' << perm[i - 1] << '\n';
    }
}

