// checker: argv[1] = test, argv[2] = odpowiedź; sprawdza, czy wypisana para (i, j) ma a[i] + a[j] == x
int main(int argc, char* argv[]) {
    if (argc < 3) return 2;
    ifstream test(argv[1]), odp(argv[2]);
    int n; long long x;
    test >> n >> x;
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; i++) test >> a[i];
    int i, j;
    if (!(odp >> i >> j) || i < 1 || j > n || i >= j || a[i] + a[j] != x) { cout << "ZLE\n"; return 1; }
    cout << "OK\n";
}

